class LibraryMember{protected String memberId;protected int borrowLimit;private int booksBorrowed;public LibraryMember(String id,int limit){if(id==null||id.trim().length()<4||limit<=0)throw new IllegalArgumentException("Invalid member details");memberId=id;borrowLimit=limit;}public void borrowBook(){if(booksBorrowed<borrowLimit)booksBorrowed++;}public int getBooksBorrowed(){return booksBorrowed;}public String displayInfo(){return "General | Books: "+booksBorrowed;}}
class StudentMember extends LibraryMember{private String course;public StudentMember(String id,int limit,String c){super(id,limit);course=c;}public String getCourse(){return course;}public String displayInfo(){return "Student | Course: "+course+" | Books: "+getBooksBorrowed();}}
public class CirculationReport{static String batchPrint(LibraryMember[] a){StringBuilder b=new StringBuilder();for(LibraryMember m:a){b.append(m.displayInfo());if(m instanceof StudentMember)b.append(" [Course via downcast: ").append(((StudentMember)m).getCourse()).append("]");b.append(" | ");}return b.toString();}public static void main(String[] args){System.out.println(batchPrint(new LibraryMember[]{new LibraryMember("LB5",3),new StudentMember("STU6",3,"ECE")}));}}